63	    }
64	    if (!sub) return { decisions: { subject: null, phase: 'none' }, state: st, close: true };
65	    const others = (ctx.instances({ subject: sub }) ?? []).filter(i => i.instance !== input.instance);
66	    if (others.length) return { decisions: { subject: sub, phase: 'merged' }, state: st, merge: { into: others[0].instance } };
67	    if (kindOf(first) !== 'placed') {
68	      // a message about an order that is already closed changes nothing; one about no order at all is answered with nothing
69	      return { decisions: { subject: sub, phase: 'closed' }, state: st, close: true };
70	    }
71	    if (ctx.query('orders.orders', { where: { orderId: sub }, limit: 1 }).length) {
72	      return { decisions: { subject: sub, phase: 'duplicate' }, state: st, close: true };   // R1.4
73	    }
74	  }
75	
76	  for (const e of events) {
77	    if (e.type === 'effect.result' || e.type === 'timer.fired' || String(e.type).startsWith('humanTask.')) {
78	      const owner = ctx.ownerOf(e);
79	      if (owner) { absorb(owner.module, ctx.deliver(e)); continue; }
80	      if (e.type === 'effect.result') readResult(e);
81	      continue;
82	    }
