200	      ctx.call('orderflow', st.o, { op: 'ended', fid: r.ended.fid, status: r.ended.status, at: r.ended.at });
201	    } else if (module === 'orderflow' && r?.done) {
202	      // the order is over and its fulfilments are terminal: nothing is pending
203	    }
