1	// Order-level decisions (SPEC-E R3, R4.1, R4.5, R6, R7.2). Key = order id.
2	// Each op only decides and records; the starts and the processing statuses are emitted by `settle`, which the parent
3	// calls once at the end of a tick, so a counted cancel in the same tick stops the order before any step is taken (S9, S10).
4	
5	const fileJson = (files, p) => {
6	  let v = files?.[p];
7	  if (v === undefined) v = p.split('/').reduce((o, k) => (o ? o[k] : undefined), files);
8	  if (typeof v === 'string') { try { v = JSON.parse(v); } catch { return null; } }
9	  return v ?? null;
10	};
11	const deepFind = (v, key, d = 0) => {
12	  if (!v || typeof v !== 'object' || d > 8) return undefined;
13	  if (!Array.isArray(v) && key in v) return v[key];
14	  for (const x of Object.values(v)) { const r = deepFind(x, key, d + 1); if (r !== undefined) return r; }
15	  return undefined;
16	};
17	const T = iso => Date.parse(iso);
18	const offOf = iso => { const m = /(Z|[+-]\d\d:\d\d)$/.exec(iso); return !m ? '+01:00' : m[1] === 'Z' ? '+00:00' : m[1]; };
19	const addMin = (iso, m) => {
20	  const off = offOf(iso), [h, mm] = off.slice(1).split(':').map(Number);
21	  const shift = (off[0] === '-' ? -1 : 1) * (h * 60 + mm);
22	  return new Date(Date.parse(iso) + m * 60000 + shift * 60000).toISOString().slice(0, 19) + off;
23	};
24	const TERMINAL = ['completed', 'failed', 'cancelled'];
25	const policy = (ctx, ed, name) => {
26	  const v = deepFind(fileJson(ctx.files, `rulebook/${ed}/policy.json`), name);
27	  if (typeof v !== 'number') throw new Error(`rulebook/${ed}/policy.json has no ${name}`);
28	  return v;
29	};
30	
31	const orderEff = (ctx, status, key) => ({ key, system: 'orders', op: 'setStatus', args: { orderId: ctx.key, fulfilmentId: null, status } });
32	const fulEff = (ctx, fid, status, key) => ({ key, system: 'orders', op: 'setStatus', args: { orderId: ctx.key, fulfilmentId: fid, status } });
33	const mail = (O, template, about, key, text) => ({ key, system: 'notify', op: 'send', args: { to: O.em, about, template, text, ref: null } });
34	const fInput = (ctx, O, f) => ({ orderId: ctx.key, fulfilmentId: f.fid, location: f.loc, customerId: O.cust, currency: O.cur, amountMinor: f.amt, items: f.items, email: O.em });
35	
36	// The order is cancelled (R6.1 / R6.2 / R2 / R3.2): every open fulfilment ends, the order is cancelled, customer notified.
37	function doCancel(ctx, O, reason, at, eff, obl) {
38	  O.ph = 'end'; O.oc = reason;
39	  for (const f of O.fl) {
40	    if (TERMINAL.includes(O.fs[f.fid])) continue;
41	    if (f.av && O.sp) {
42	      // started: compensate what committed and set it cancelled (R6.2); its result may come later
43	      const r = ctx.call('fulfilment', f.fid, { op: 'cancel', at, reason });
44	      if (r?.ended) O.fs[f.fid] = r.ended.status;
45	    } else {
46	      O.fs[f.fid] = 'cancelled';
47	      eff.push(fulEff(ctx, f.fid, 'cancelled', `f.${f.fid}.cancelled`));
48	    }
49	  }
50	  eff.push(orderEff(ctx, 'cancelled', 'o.cancelled'));
51	  eff.push(mail(O, 'order-cancelled', ctx.key, 'n.cancelled', `Order ${ctx.key} has been cancelled.`));
52	}
53	
54	// The customer amends (R3.2): unavailable fulfilments are cancelled; the order is ready at the amend's time.
55	function amend(ctx, O, at, eff, obl) {
56	  for (const f of O.fl) {
57	    if (f.av) continue;
58	    O.fs[f.fid] = 'cancelled';
59	    eff.push(fulEff(ctx, f.fid, 'cancelled', `f.${f.fid}.cancelled`));
60	  }
61	  if (!O.fl.some(f => f.av)) return doCancel(ctx, O, 'nothing-available', at, eff, obl);
62	  O.ph = 'proc'; O.cl = at;
63	}
64	
65	// The settle pass: the R3.1 notice, and the R4.1 processing statuses with each available fulfilment's saga started.
66	export function settle(ctx, O) {
67	  const eff = [];
68	  if (O.ph === 'wait' && !O.sar) {
69	    O.sar = true;
70	    eff.push(orderEff(ctx, 'customerActionRequired', 'o.action'));
71	    eff.push(mail(O, 'action-required', ctx.key, 'n.action', `Some items of order ${ctx.key} are unavailable. Please amend or cancel the order.`));
72	  }
73	  if (O.ph === 'proc' && !O.sp) {
74	    O.sp = true;
75	    eff.push(orderEff(ctx, 'processing', 'o.processing'));
76	    for (const f of O.fl) if (f.av) eff.push(fulEff(ctx, f.fid, 'processing', `f.${f.fid}.processing`));
77	    for (const f of O.fl) if (f.av) ctx.call('fulfilment', f.fid, { op: 'start', fulfilment: fInput(ctx, O, f) });
78	  }
79	  return eff;
80	}
81	
82	function dispatch(op, I, ctx) {
83	  let O = ctx.state;
84	  const eff = [], obl = { upsert: [], cancel: [] };
85	  if (op === 'record') {
86	    if (O) return { output: { done: false }, state: O, effects: [], obligations: obl };
87	    O = { ph: 'pend', p: I.p, ed: I.ed, em: I.em, cur: I.cur, cust: I.cust, fl: I.fl, fs: {}, cl: null, D: null, coll: null, sar: false, sp: false, oc: null };
88	    return { output: { done: false }, state: O, effects: [], obligations: obl };
89	  }
90	  if (!O) return { output: { done: false }, state: null, effects: [], obligations: obl };
91	  const prev = O.ph;
92	  if (op === 'cleared') {
93	    // R2.1 pass / R2.2 approve: cleared at the given time (R4.1 ready, or R3.1 waiting for the customer)
94	    if (O.ph === 'pend') {
95	      O.cl = I.at;
96	      if (O.fl.some(f => !f.av)) {
97	        O.ph = 'wait';
98	        O.D = addMin(O.p, policy(ctx, O.ed, 'customerActionHours') * 60);
99	        obl.upsert.push({ id: 'deadline', kind: 'customerDeadline', anchor: O.p, dueAt: addMin(O.D, 60), onDue: 'deadline' });
100	      } else O.ph = 'proc';
101	    }
102	  } else if (op === 'reject') {
103	    // R2.1 reject, R2.2 reject / no usable answer: cancelled for fraud before any step
104	    if (O.ph === 'pend') doCancel(ctx, O, I.reason, I.at, eff, obl);
105	  } else if (op === 'action') {
106	    if (I.action === 'amend') {
107	      // R3.2: the first amend at or before D counts while waiting (S5, S8: later amends change nothing)
108	      if (O.ph === 'wait' && T(I.at) <= T(O.D)) amend(ctx, O, I.at, eff, obl);
109	    } else if (I.action === 'cancel') {
110	      if (O.ph === 'pend') doCancel(ctx, O, 'customer', I.at, eff, obl);                 // R6.4
111	      else if (O.ph === 'wait') { if (T(I.at) <= T(O.D)) doCancel(ctx, O, 'customer', I.at, eff, obl); }   // R3.2
112	      else if (O.ph === 'proc') {
113	        // R6.2: counts unless a collection was reported at or before the cancel (S7)
114	        if (O.coll !== null && T(O.coll) <= T(I.at)) {
115	          eff.push(mail(O, 'cancel-refused', ctx.key, `n.refused.${String(I.eid).replace(/\//g, '_')}`, `The order ${ctx.key} has been collected and can no longer be cancelled.`));
116	        } else doCancel(ctx, O, 'customer', I.at, eff, obl);
117	      }
118	    }
119	  } else if (op === 'evidence') {
120	    // a collection-proving report (S7): keep the earliest reportedAt
121	    if (O.coll === null || T(I.reportedAt) < T(O.coll)) O.coll = I.reportedAt;
122	  } else if (op === 'ended') {
123	    // R4.5: the order's outcome once every available fulfilment has ended
124	    O.fs[I.fid] = I.status;
125	    if (O.ph === 'proc' && O.fl.filter(f => f.av).every(f => TERMINAL.includes(O.fs[f.fid]))) {
126	      const fs = O.fl.filter(f => f.av).map(f => O.fs[f.fid]);
127	      O.ph = 'end';
128	      O.oc = fs.includes('completed') ? 'completed' : fs.includes('failed') ? 'failed' : 'cancelled';
129	      eff.push(orderEff(ctx, O.oc, 'o.outcome'));
130	    }
131	  } else if (op === 'timeout') {
132	    // R3.2: nothing counted by D: after D (and by D + 60 min) every fulfilment is cancelled and the order times out
133	    if (O.ph === 'wait' && T(I.now) >= T(O.D)) {
134	      O.ph = 'end'; O.oc = 'timedOut';
135	      for (const f of O.fl) {
136	        if (TERMINAL.includes(O.fs[f.fid])) continue;
137	        O.fs[f.fid] = 'cancelled';
138	        eff.push(fulEff(ctx, f.fid, 'cancelled', `f.${f.fid}.cancelled`));
139	      }
140	      eff.push(orderEff(ctx, 'timedOut', 'o.timedOut'));
141	      eff.push(mail(O, 'order-timed-out', ctx.key, 'n.timed-out', `Order ${ctx.key} timed out: it was not confirmed in time.`));
142	    }
143	  } else if (op === 'resume') {
144	    // go-live (§3.5): continue an order in flight from the status its records show; nothing is re-announced
145	    O.fs = { ...O.fs, ...(I.fs ?? {}) };
146	    if (I.status === 'customerActionRequired' && O.ph === 'pend') {
147	      O.ph = 'wait'; O.cl = O.p; O.sar = true;
148	      O.D = addMin(O.p, policy(ctx, O.ed, 'customerActionHours') * 60);
149	      obl.upsert.push({ id: 'deadline', kind: 'customerDeadline', anchor: O.p, dueAt: addMin(O.D, 60), onDue: 'deadline' });
150	    } else if (I.status === 'processing' && O.ph === 'pend') {
151	      O.ph = 'proc'; O.cl = O.p; O.sp = true;
152	    } else if (['completed', 'failed', 'cancelled', 'timedOut'].includes(I.status)) {
153	      O.ph = 'end'; O.oc = I.status;
154	    }
155	  } else if (op === 'settle') {
156	    eff.push(...settle(ctx, O));
157	  } else throw new Error(`orderflow: unknown op ${op}`);
158	  if (prev === 'wait' && O.ph !== 'wait') obl.cancel.push('deadline');
159	  const done = O.ph === 'end' && O.fl.every(f => TERMINAL.includes(O.fs[f.fid]));
160	  return { output: { done }, state: O, effects: eff, obligations: obl };
161	}
162	
163	export function step(input, ctx) {
164	  return dispatch(input.op, input, ctx);
165	}
166	
167	export function onEvent(event, ctx) {
168	  if (event.type === 'timer.fired' && event.payload?.obligationId === 'deadline') return dispatch('timeout', { now: ctx.now }, ctx);
169	  // results of this order's own status changes and notices need no decision
170	  return { output: { done: false }, state: ctx.state };
171	}
