    const others = (ctx.instances({ subject: sub }) ?? []).filter(i => i.instance !== input.instance);
    if (others.length) return { decisions: { subject: sub, phase: 'merged' }, state: st, merge: { into: others[0].instance } };
    if (kindOf(first) !== 'placed') {
