    }
  }

  function verdict(v) {
    const r = ctx.call('fraud', st.o, { op: 'verdict', verdict: v, at: st.p, edition: st.ed });
    absorb('fraud', r);
  }

  function absorb(module, r) {
    if (module === 'fraud' && r?.outcome) {
      const o = r.outcome;
      if (o.kind === 'cleared') ctx.call('orderflow', st.o, { op: 'cleared', at: o.at });
